use xiom.io;

use xiom.string;
module auth {
  fn hash_password(pw: Str) -> Str {
    return "hashed_" + pw;
  }

  pub fn check_password(pw: Str) -> Bool {
    return string.str_len(pw) > 0;
  }

  pub fn login(pw: Str) -> Str {
    if check_password(pw) {
      return "Welcome!";
    }
    return "Denied";
  }
}

fn main() -> Int {
  io.println(auth.login("secret"));
  return 0;
}
